def fibonacci(n):
    """Calculates F_n using iterative method for large integers."""
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def lucas(n):
    """Calculates L_n using iterative method for large integers."""
    if n == 0:
        return 2
    if n == 1:
        return 1
    a, b = 2, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

# 1. Calculate L_100
L_100 = lucas(100)
